{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-cards.json
    The features as a grid of cards, tiles or bordered cells (the body of FeatureGrid). Icons are Lucide names.
    Props (p): features, cols, item. -#}
{%- set v_features = (p.features ?? null) -%}
{%- set v_cols = (p.cols ?? '1-3') -%}
{%- set v_item = (p.item ?? 'card') -%}
{%- set c_15 -%}
  {%- for v_feature in ui_l(v_features) %}
    {%- if ui_t(ui_eq(v_item, 'tile')) %}
      {%- set c_5 -%}
        {%- set c_4 -%}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s(ui_get(v_feature, ['icon'])), 'Size': 20}}, with_context = false) }}
          {%- set c_3 -%}
            {%- set c_1 -%}
              {{ ui_text(ui_get(v_feature, ['title'])) }}
            {%- endset -%}
            {{ include('ui/title/title.html.twig', {'p': {'As': ui_i(3), 'Size': 'base', 'Weight': 'bold'}, 'children': c_1}, with_context = false) }}
            {%- set c_2 -%}
              {{ ui_text(ui_get(v_feature, ['text'])) }}
            {%- endset -%}
            {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Class': 'text-muted-foreground'}, 'children': c_2}, with_context = false) }}
          {%- endset -%}
          {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '2'}, 'children': c_3}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'start'}, 'children': c_4}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/card/card.html.twig', {'p': {'Variant': 'compact', 'Attrs': ui_attrs(['data-testid', 'feature-card'])}, 'children': c_5}, with_context = false) }}
    {%- elseif ui_t(ui_eq(v_item, 'cell')) %}
      {%- set c_9 -%}
        {%- set c_6 -%}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s(ui_get(v_feature, ['icon'])), 'Size': 24}}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/iconbadge/icon-badge.html.twig', {'p': {'Variant': 'primary', 'Size': 'xl', 'Attrs': ui_attrs(['data-testid', 'feature-icon'])}, 'children': c_6}, with_context = false) }}
        {%- set c_7 -%}
          {{ ui_text(ui_get(v_feature, ['title'])) }}
        {%- endset -%}
        {{ include('ui/title/title.html.twig', {'p': {'As': ui_i(3), 'Size': 'xl', 'Weight': 'semibold', 'Class': 'leading-6'}, 'children': c_7}, with_context = false) }}
        {%- set c_8 -%}
          {{ ui_text(ui_get(v_feature, ['text'])) }}
        {%- endset -%}
        {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold', 'Class': 'leading-5 text-muted-foreground'}, 'children': c_8}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '2', 'Align': 'center', 'Class': 'h-full gap-8 bg-background px-6 py-12 text-center', 'Attrs': ui_attrs(['data-testid', 'feature-card'])}, 'children': c_9}, with_context = false) }}
    {%- else %}
      {%- set c_14 -%}
        {%- set c_11 -%}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s(ui_get(v_feature, ['icon'])), 'Size': 24}}, with_context = false) }}
          {%- set c_10 -%}
            {{ ui_text(ui_get(v_feature, ['title'])) }}
          {%- endset -%}
          {{ include('ui/card/card-title.html.twig', {'p': {'As': ui_i(3)}, 'children': c_10}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/card/card-header.html.twig', {'p': {'Class': 'flex flex-col gap-4'}, 'children': c_11}, with_context = false) }}
        {%- set c_13 -%}
          {%- set c_12 -%}
            {{ ui_text(ui_get(v_feature, ['text'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Class': 'text-muted-foreground'}, 'children': c_12}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/card/card-content.html.twig', {'p': {}, 'children': c_13}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/card/card.html.twig', {'p': {'Variant': 'default', 'Attrs': ui_attrs(['data-testid', 'feature-card'])}, 'children': c_14}, with_context = false) }}
    {%- endif %}
  {%- endfor %}
{%- endset -%}
{{ include('ui/grid/grid.html.twig', {'p': {'Cols': ui_s(v_cols), 'Class': ui_s((ui_t(ui_eq(v_item, 'cell')) ? ui_cnv(['w-full gap-px overflow-hidden bg-border p-px', ui_preset('blocks/presets/defaults.json', ['features', 'cells'])]) : 'gap-6')), 'Attrs': ui_attrs(['data-testid', 'feature-grid'])}, 'children': c_15}, with_context = false) }}
